css:
.d-text-case-transform{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-text-case-transform *,.d-text-case-transform *::before,.d-text-case-transform *::after{box-sizing:border-box}
.d-text-case-transform [hidden]{display:none!important}
.d-text-case-transform .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-text-case-transform .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-text-case-transform label{display:block;margin:8px 0}
.d-text-case-transform input,.d-text-case-transform select,.d-text-case-transform textarea,.d-text-case-transform button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-text-case-transform input:not([type=checkbox]):not([type=radio]),.d-text-case-transform select,.d-text-case-transform textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-text-case-transform button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-text-case-transform button:disabled{opacity:.5;cursor:default}
.d-text-case-transform :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-text-case-transform [aria-invalid=true]{border-color:var(--warn)!important}
.d-text-case-transform .d-scroll{max-width:100%;overflow:auto}
.d-text-case-transform table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-text-case-transform th,.d-text-case-transform td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-text-case-transform caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-text-case-transform progress{width:100%;accent-color:var(--ink)}
.d-text-case-transform pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-text-case-transform h3,.d-text-case-transform p{margin:8px 0}
.d-text-case-transform [aria-pressed=true],.d-text-case-transform [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-text-case-transform .d-grow{flex:1;min-width:100px}
.d-text-case-transform summary{cursor:pointer;padding:6px 0}
.d-text-case-transform ul,.d-text-case-transform ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-result]').readOnly=true;q('[data-convert]').onclick=()=>{const text=q('[data-input]').value,mode=q('[data-mode]').value;q('[data-result]').value=mode==='upper'?text.toLocaleUpperCase():mode==='lower'?text.toLocaleLowerCase():text.trim().replace(/\s+/g,' ');say(text?'转换完成，原文保留':'原文为空，结果已清空');};})(root, q, qa, say);
}
